Spot the bug in this KD-tree nearest-neighbour recursion:
```cpp
void search(int node, const Vector3d& q, int& best, double& best_d2) {
  // ... leaf handling ...
  double diff = q[n.axis] - n.split;
  int near = diff < 0 ? n.left : n.right;
  int far  = diff < 0 ? n.right : n.left;
  search(near, q, best, best_d2);
  if (std::abs(diff) < best_d2) search(far, q, best, best_d2);
}
```
